// Simulated DOM
const elements = new Map();

function createElement(tag, id, text) {
  const el = { tag, id, text, children: [], style: {} };
  elements.set(id, el);
  return el;
}

function setText(id, text) {
  const el = elements.get(id);
  if (el) el.text = text;
}

function addClass(id, cls) {
  const el = elements.get(id);
  if (el) {
    if (!el.classes) el.classes = [];
    el.classes.push(cls);
  }
}

function render(id) {
  const el = elements.get(id);
  if (!el) return '';
  let html = '<' + el.tag;
  if (el.classes && el.classes.length) {
    html += ' class="' + el.classes.join(' ') + '"';
  }
  html += '>' + (el.text || '');
  for (const child of el.children) {
    html += render(child);
  }
  html += '</' + el.tag + '>';
  return html;
}

